input.command:
npm init -y >/dev/null && npm i xrpl@latest >/dev/null 2>&1 && npm i -D typescript@latest tsx @types/node >/dev/null 2>&1 && cat package.json | grep -A6 depend && cat > /tmp/probe.mjs <<'EOF'
import { Client } from 'xrpl';
const c = new Client('wss://s.altnet.rippletest.net:51233'); await c.connect();
const a = await c.request({command:'account_info', account:'rUhQUNEr2hpEq16zJWNgtMpAdmPH2sV3qs'});
console.log(JSON.stringify(a.result.account_data));
const o = await c.request({command:'account_objects', account:'rUhQUNEr2hpEq16zJWNgtMpAdmPH2sV3qs'});
console.log(JSON.stringify(o.result.account_objects));
const s = await c.request({command:'server_state'}); console.log(JSON.stringify(s.result.state.validated_ledger), s.result.state.build_version);
const f = await c.request({command:'feature'}); const feats=Object.values(f.result.features).filter(x=>/MPT|Clawback|SingleAsset/i.test(x.name)).map(x=>[x.name,x.enabled]); console.log(feats);
await c.disconnect();
EOF
cp /tmp/probe.mjs ./probe.mjs && node probe.mjs; rm probe.mjs

