import type { Client, SubmittableTransaction, TransactionMetadata, Wallet } from 'xrpl';
import { TransactionFailedError, TransactionOutcomeUnknownError } from './errors.js';
import type { AuditLogger } from './logger.js';

export interface SubmittedTransaction {
  hash: string;
  ledgerIndex: number;
  engineResult: 'tesSUCCESS';
  meta: TransactionMetadata;
}

export interface SubmitOptions {
  /** Ledgers the transaction stays valid for after autofill. Default 20 (~60-80s). */
  ledgerWindow?: number;
  /** How often to poll for the validated result. Default 1000ms. */
  pollIntervalMs?: number;
  /** Retries when the sequence was consumed concurrently (tefPAST_SEQ). Default 2. */
  maxSequenceRetries?: number;
}

const DEFAULTS: Required<SubmitOptions> = {
  ledgerWindow: 20,
  pollIntervalMs: 1000,
  maxSequenceRetries: 2,
};

/**
 * Preliminary results that mean the transaction was not applied and can never
 * be applied in its current signed form. Anything else (tes, tec, ter, and
 * errors like tefMAX_LEDGER from a stale view) is inconclusive: the
 * transaction might still make it into a validated ledger, so we wait for
 * the final outcome instead of guessing.
 */
function isDefinitivePreliminaryFailure(result: string): boolean {
  return result.startsWith('tem') || result.startsWith('tel') || (result.startsWith('tef') && result !== 'tefMAX_LEDGER');
}

const sleep = (ms: number) => new Promise<void>((resolve) => setTimeout(resolve, ms));

/**
 * Signs `tx` locally with `wallet`, submits it, and waits until it is in a
 * validated ledger or has provably expired (LastLedgerSequence passed).
 *
 * Resolves only when the transaction validated with tesSUCCESS. Throws
 * {@link TransactionFailedError} for any definitive failure (including
 * validated tec* results, which consume a fee but do nothing else), and
 * {@link TransactionOutcomeUnknownError} if the outcome can't be established.
 */
export async function submitAndConfirm(
  client: Client,
  wallet: Wallet,
  tx: SubmittableTransaction,
  logger: AuditLogger,
  options: SubmitOptions = {},
): Promise<SubmittedTransaction> {
  const opts = { ...DEFAULTS, ...options };
  if (tx.Account !== wallet.classicAddress) {
    throw new TransactionFailedError(
      `Transaction Account ${tx.Account} does not match signing wallet ${wallet.classicAddress}`,
      'localMISMATCHED_SIGNER',
      undefined,
      false,
    );
  }

  for (let attempt = 0; ; attempt++) {
    const prepared = await client.autofill({ ...tx, LastLedgerSequence: undefined });
    const currentLedger = await client.getLedgerIndex();
    prepared.LastLedgerSequence = currentLedger + opts.ledgerWindow;
    const { tx_blob, hash } = wallet.sign(prepared);
    const lastLedgerSequence = prepared.LastLedgerSequence;

    logger.debug('tx.submit', { type: tx.TransactionType, hash, sequence: prepared.Sequence, lastLedgerSequence });
    const submitResponse = await client.request({ command: 'submit', tx_blob });
    const preliminary = submitResponse.result.engine_result;

    if (preliminary === 'tefPAST_SEQ' && attempt < opts.maxSequenceRetries) {
      // Our Sequence was used by another transaction, so this signed blob can
      // never apply. It's safe to re-autofill and try again.
      logger.warn('tx.retry_sequence', { type: tx.TransactionType, hash, attempt });
      continue;
    }
    if (isDefinitivePreliminaryFailure(preliminary)) {
      throw new TransactionFailedError(
        `${tx.TransactionType} rejected: ${preliminary} (${submitResponse.result.engine_result_message})`,
        preliminary,
        hash,
        false,
      );
    }

    return await waitForValidation(client, tx.TransactionType, hash, lastLedgerSequence, preliminary, opts);
  }
}

async function waitForValidation(
  client: Client,
  type: string,
  hash: string,
  lastLedgerSequence: number,
  preliminary: string,
  opts: Required<SubmitOptions>,
): Promise<SubmittedTransaction> {
  for (;;) {
    await sleep(opts.pollIntervalMs);
    let found: Awaited<ReturnType<typeof lookupTx>>;
    try {
      found = await lookupTx(client, hash);
    } catch (error) {
      throw new TransactionOutcomeUnknownError(
        `Lost track of ${type} ${hash} (preliminary ${preliminary}); look it up before retrying`,
        hash,
        lastLedgerSequence,
        { cause: error },
      );
    }

    if (found?.validated) {
      const meta = found.meta;
      const result = meta.TransactionResult;
      if (result !== 'tesSUCCESS') {
        throw new TransactionFailedError(`${type} ${hash} failed in validated ledger: ${result}`, result, hash, true);
      }
      return { hash, ledgerIndex: found.ledgerIndex, engineResult: 'tesSUCCESS', meta };
    }

    // Not validated yet. Once the latest validated ledger is past
    // LastLedgerSequence (and our server has every ledger in that window), the
    // transaction can never be included.
    const validatedLedger = await client.getLedgerIndex();
    if (validatedLedger > lastLedgerSequence) {
      // Re-check once to close the race between the lookup and the ledger index read.
      const recheck = await lookupTx(client, hash);
      if (recheck?.validated) {
        continue;
      }
      throw new TransactionFailedError(
        `${type} ${hash} expired without validating (preliminary ${preliminary}, LastLedgerSequence ${lastLedgerSequence})`,
        preliminary,
        hash,
        false,
      );
    }
  }
}

async function lookupTx(
  client: Client,
  hash: string,
): Promise<{ validated: boolean; meta: TransactionMetadata; ledgerIndex: number } | null> {
  try {
    const response = await client.request({ command: 'tx', transaction: hash });
    const { validated, meta, ledger_index } = response.result;
    if (!validated || typeof meta !== 'object' || meta === null || ledger_index === undefined) {
      return { validated: false, meta: meta as TransactionMetadata, ledgerIndex: ledger_index ?? 0 };
    }
    return { validated: true, meta: meta as TransactionMetadata, ledgerIndex: ledger_index };
  } catch (error) {
    if (isTxnNotFound(error)) {
      return null;
    }
    throw error;
  }
}

function isTxnNotFound(error: unknown): boolean {
  const data = (error as { data?: { error?: string } } | null)?.data;
  return data?.error === 'txnNotFound';
}

