import { dirname } from 'node:path';

export interface BanRecord {
  address: string;
  issuanceId: string;
  reason: string;
  bannedAt: string;
  /** Set once the ban has been fully enforced on ledger. */
  enforcedAt?: string;
  txHashes: string[];
}

/**
