      Account: issuerWallet.classicAddress,
      Destination: destination,
      Amount: { mpt_issuance_id: issuanceId, value },
    },
    logger,
  );
}

main().catch((error: unknown) => {
  console.error('\nDEMO FAILED:', error);
  process.exitCode = 1;
});

