import { readFileSync } from 'node:fs';
import { Client } from 'xrpl';
const r = JSON.parse(readFileSync('result.json', 'utf8'));
const c = new Client('wss://s.altnet.rippletest.net:51233'); await c.connect();
const iss = await c.request({ command: 'ledger_entry', mpt_issuance: r.issuanceId, ledger_index: 'validated' });
const n = iss.result.node;
console.log('issuance', { Issuer: n.Issuer, Flags: '0x' + n.Flags.toString(16), OutstandingAmount: n.OutstandingAmount, AssetScale: n.AssetScale });
for (const [k, a] of Object.entries(r.holders)) {
  const t = (await c.request({ command: 'ledger_entry', mptoken: { mpt_issuance_id: r.issuanceId, account: a }, ledger_index: 'validated' })).result.node;
  console.log(k, a, { MPTAmount: t.MPTAmount ?? '0', Flags: '0x' + t.Flags.toString(16) });
}
const objs = await c.request({ command: 'account_objects', account: 'rUhQUNEr2hpEq16zJWNgtMpAdmPH2sV3qs', ledger_index: 'validated' });
console.log('issuer objects', objs.result.account_objects.map((o) => o.LedgerEntryType));
console.log('issuer XRP', await c.getXrpBalance('rUhQUNEr2hpEq16zJWNgtMpAdmPH2sV3qs'));
await c.disconnect();

